/**
 * The disposition vocabulary, in one place.
 *
 * `dialer_call_logs.disposition_status` accepts exactly these thirteen labels,
 * and `status_group` is generated by the database with the same mapping. The
 * screen, the service and the RPC therefore cannot disagree about what a chip
 * means or whether a call reached a conversation.
 *
 * This module deliberately has no `server-only` import: the chips are rendered
 * by a client component, and the labels are the data model, not a translation.
 */

export type DispositionStatus =
  | "CONFIRMED"
  | "MAY_COME"
  | "WILL_COME_NEXT_CLASS"
  | "WILL_COME_NEXT_WEEK"
  | "VISITING_HOME_TOWN"
  | "CALL_ME_BACK"
  | "CALL_DID_NOT_CONNECT"
  | "HEALTH_IS_NOT_GOOD"
  | "SWITCHED_OFF"
  | "OUT_OF_STATION"
  | "BUSY_CANNOT_COME"
  | "WRONG_NUMBER"
  | "NOT_INTERESTED"

export type DispositionStatusGroup =
  | "CONFIRMED"
  | "MAY_COME"
  | "DEFERRED"
  | "NOT_REACHABLE"
  | "WRONG_NUMBER"
  | "NOT_INTERESTED"

export interface DispositionOption {
  status: DispositionStatus
  label: string
  group: DispositionStatusGroup
}

/**
 * The order is frame 2456's chip order, top to bottom and left to right:
 * Confirmed, May come, Will come next class, Will come next week, Visiting home
 * town, Call me back, Call did not connect, Health is not good, Switched off,
 * Out of station, Busy cannot come, Wrong number, Not interested - do not call
 * again.
 */
export const DISPOSITION_OPTIONS: readonly DispositionOption[] = [
  { status: "CONFIRMED", label: "Confirmed", group: "CONFIRMED" },
  { status: "MAY_COME", label: "May come", group: "MAY_COME" },
  { status: "WILL_COME_NEXT_CLASS", label: "Will come next class", group: "DEFERRED" },
  { status: "WILL_COME_NEXT_WEEK", label: "Will come next week", group: "DEFERRED" },
  { status: "VISITING_HOME_TOWN", label: "Visiting home town", group: "DEFERRED" },
  { status: "CALL_ME_BACK", label: "Call me back", group: "DEFERRED" },
  { status: "CALL_DID_NOT_CONNECT", label: "Call did not connect", group: "NOT_REACHABLE" },
  { status: "HEALTH_IS_NOT_GOOD", label: "Health is not good", group: "DEFERRED" },
  { status: "SWITCHED_OFF", label: "Switched off", group: "NOT_REACHABLE" },
  { status: "OUT_OF_STATION", label: "Out of station", group: "DEFERRED" },
  { status: "BUSY_CANNOT_COME", label: "Busy cannot come", group: "DEFERRED" },
  { status: "WRONG_NUMBER", label: "Wrong number", group: "WRONG_NUMBER" },
  { status: "NOT_INTERESTED", label: "Not interested — do not call again", group: "NOT_INTERESTED" },
] as const

const DISPOSITION_BY_STATUS = new Map(
  DISPOSITION_OPTIONS.map((option) => [option.status, option] as const),
)

const REACHED_GROUPS: readonly DispositionStatusGroup[] = [
  "CONFIRMED",
  "MAY_COME",
  "DEFERRED",
  "NOT_INTERESTED",
]

const NOT_REACHABLE_GROUPS: readonly DispositionStatusGroup[] = ["NOT_REACHABLE", "WRONG_NUMBER"]

export function isDispositionStatus(value: unknown): value is DispositionStatus {
  return typeof value === "string" && DISPOSITION_BY_STATUS.has(value as DispositionStatus)
}

export function dispositionGroupFor(status: DispositionStatus): DispositionStatusGroup {
  return DISPOSITION_BY_STATUS.get(status)?.group ?? "DEFERRED"
}

/**
 * A call reached a conversation when its group is anything except
 * `NOT_REACHABLE` or `WRONG_NUMBER`. The campaign survey renders only then.
 */
export function isReachedGroup(group: string): boolean {
  return REACHED_GROUPS.includes(group as DispositionStatusGroup)
}

export function isNotReachedGroup(group: string): boolean {
  return NOT_REACHABLE_GROUPS.includes(group as DispositionStatusGroup)
}

export function dispositionLabel(status: string): string {
  return isDispositionStatus(status) ? DISPOSITION_BY_STATUS.get(status)!.label : status
}

/**
 * The short group labels used by the queue and the session summary. These are
 * display strings only; the stored `status_group` is the database's value.
 */
export const STATUS_GROUP_LABELS: Record<DispositionStatusGroup, string> = {
  CONFIRMED: "Confirmed",
  MAY_COME: "May come",
  DEFERRED: "Deferred",
  NOT_REACHABLE: "No answer",
  WRONG_NUMBER: "Wrong number",
  NOT_INTERESTED: "Not interested",
}
